package common

import chisel3._
import chisel3.util._

object ForceZero {
  def apply[T <: Data](in: Valid[T]): Valid[T] = {
    val out = Wire(Valid(chiselTypeOf(in.bits)))
    out.valid := in.valid
    out.bits := Mux(in.valid, in.bits, 0.U.asTypeOf(in.bits))
    out
  }
}

object Zip32 {
  def apply(sz: UInt, a: UInt, b: UInt): UInt = {
    val out = Wire(UInt(64.W))
    out := MuxLookup(sz, 0.U(64.W))(Seq(
      4.U -> (b ## a),
      2.U -> {
        val a0 = a(15, 0)
        val a1 = a(31, 16)
        val b0 = b(15, 0)
        val b1 = b(31, 16)
        b1 ## a1 ## b0 ## a0
      },
      1.U -> {
        val a0 = a(7, 0)
        val a1 = a(15, 8)
        val a2 = a(23, 16)
        val a3 = a(31, 24)
        val b0 = b(7, 0)
        val b1 = b(15, 8)
        val b2 = b(23, 16)
        val b3 = b(31, 24)
        b3 ## a3 ## b2 ## a2 ## b1 ## a1 ## b0 ## a0
      }
    ))
    out
  }
}

object RotateVectorLeft {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      out(i) := in((i - shift).asSInt.asUInt)
    }

    for (i <- 0 until n) {
      val sel = Wire(UInt(log2Ceil(n).W))
      sel := 0.U
      for (s <- 0 until n) {
        when(shift === s.U) {
          sel := ((i - s + n) % n).U
        }
      }
      out(i) := in(sel)
    }

    for (s <- (n - 1) to 0 by -1) {
      when(shift === s.U) {
        for (i <- 0 until n) {
          out(i) := in((i - s + n) % n)
        }
      }
    }
    out
  }
}

object RotateVectorRight {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))

    for (s <- (n - 1) to 0 by -1) {
      when(shift === s.U) {
        for (i <- 0 until n) {
          out(i) := in((i + s) % n)
        }
      }
    }
    out
  }
}

object ShiftVectorLeft {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))

    for (s <- (n - 1) to 0 by -1) {
      when(shift === s.U) {
        for (i <- 0 until n) {
          val srcIdx = i - s
          if (srcIdx < 0) {
            out(i).valid := false.B
            out(i).bits := 0.U.asTypeOf(chiselTypeOf(in(0).bits))
          } else {
            out(i) := in(srcIdx)
          }
        }
      }
    }
    out
  }
}

object ShiftVectorRight {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))

    for (s <- (n - 1) to 0 by -1) {
      when(shift === s.U) {
        for (i <- 0 until n) {
          val srcIdx = i + s
          if (srcIdx >= n) {
            out(i).valid := false.B
            out(i).bits := 0.U.asTypeOf(chiselTypeOf(in(0).bits))
          } else {
            out(i) := in(srcIdx)
          }
        }
      }
    }
    out
  }
}

