package common

import chisel3._
import chisel3.util._
import chisel3.reflect.DataMirror

object GenerateInterface {
  def apply(io: Data, prefix: String): String = {
    val lines = scala.collection.mutable.ArrayBuffer[String]()

    def processElement(d: Data, name: String, isOutput: Boolean): Unit = {
      d match {
        case b: Bundle =>
          val elements = b.elements.toSeq
          for ((fieldName, fieldData) <- elements) {
            val fullName = s"${name}_${fieldName}"
            val fieldIsOutput = if (fieldData.specifiedDirection == ActualDirection.Output ||
                fieldData.specifiedDirection == ActualDirection.Bidirectional(ActualDirection.Output)) true
              else if (fieldData.specifiedDirection == ActualDirection.Input ||
                fieldData.specifiedDirection == ActualDirection.Bidirectional(ActualDirection.Input)) false
              else isOutput
            processElement(fieldData, fullName, fieldIsOutput)
          }
        case v: Vec[_] =>
          for (i <- 0 until v.length) {
            processElement(v(i), s"${name}_${i}", isOutput)
          }
        case _ =>
          val width = d.getWidth match {
            case 1 => ""
            case w => s" [${w - 1}:0]"
          }
          val direction = if (isOutput) "output" else "input "
          lines += s"${direction} logic${width} ${name}"
      }
    }

    io match {
      case b: Bundle =>
        val elements = b.elements.toSeq
        for ((fieldName, fieldData) <- elements) {
          val fullName = s"${prefix}_${fieldName}"
          val fieldIsOutput = DataMirror.directionOf(fieldData) == ActualDirection.Output
          processElement(fieldData, fullName, fieldIsOutput)
        }
      case _ =>
        processElement(io, prefix, DataMirror.directionOf(io) == ActualDirection.Output)
    }

    lines.mkString(",\n")
  }
}

