package common

import chisel3._
import chisel3.util._

object Gather {
  def apply[T <: Data](indices: Seq[UInt], data: Seq[T]): Seq[T] = {
    val n = indices.length
    val result = Wire(Vec(n, chiselTypeOf(data(0))))
    for (i <- 0 until n) {
      result(i) := MuxLookup(indices(i), 0.U.asTypeOf(chiselTypeOf(data(0))))(
        (0 until n).map(j => j.U -> data(j))
      )
    }
    result
  }
}

object Scatter {
  def apply[T <: Data](
      indicesValid: Seq[Bool],
      indices: Seq[UInt],
      data: Seq[T]
  ): (Vec[T], Vec[Bool], Vec[Bool]) = {
    val n = indices.length
    val result = Wire(Vec(n, chiselTypeOf(data(0))))
    val writeMask = Wire(Vec(n, Bool()))
    val indicesSelected = Wire(Vec(n, Bool()))

    for (j <- 0 until n) {
      writeMask(j) := false.B
      result(j) := 0.U.asTypeOf(chiselTypeOf(data(0)))
    }

    for (i <- 0 until n) {
      indicesSelected(i) := false.B
    }

    for (j <- 0 until n) {
      var assigned = false.B
      for (i <- 0 until n) {
        when(indicesValid(i) && indices(i) === j.U && !assigned) {
          result(j) := data(i)
          writeMask(j) := true.B
          indicesSelected(i) := true.B
          assigned = true.B
        }
      }
    }

    (result, writeMask, indicesSelected)
  }
}

