package common

import chisel3._
import chisel3.util._

class IndexAllocatorIO(idxWidth: Int) extends Bundle {
  val alloc = new Bundle {
    val ready = Input(Bool())
    val valid = Output(Bool())
    val bits  = Output(UInt(idxWidth.W))
  }
  val free = new Bundle {
    val ready = Output(Bool())
    val valid = Input(Bool())
    val bits  = Input(UInt(idxWidth.W))
  }
}

abstract class IndexAllocator(val capacity: Int) extends Module {
  val io = new IndexAllocatorIO(log2Ceil(capacity))
}

class IndexAllocatorShifting(capacity: Int) extends IndexAllocator(capacity) {
  val freeMask = RegInit((1 << capacity) - 1)
  val freeIdx = PriorityEncoder(freeMask)

  val freeBit = WireDefault(0.U(capacity.W))
  when(io.free.valid && io.free.ready) {
    freeBit := (1.U << io.free.bits).asUInt
  }

  val allocBit = WireDefault(0.U(capacity.W))
  when(io.alloc.ready && io.alloc.valid) {
    allocBit := (1.U << freeIdx).asUInt
  }

  freeMask := (freeMask & ~allocBit) | freeBit

  io.alloc.valid := freeMask =/= 0.U
  io.alloc.bits := freeIdx

  io.free.ready := freeMask =/= ((1 << capacity) - 1).U
}

