package common

import chisel3._
import chisel3.util._

class CoralNPURRArbiter[T <: Data](gen: T, n: Int) extends Module {
  val io = IO(new Bundle {
    val in = Vec(n, Flipped(Decoupled(gen)))
    val out = Decoupled(gen)
    val chosen = Output(UInt(log2Ceil(n).W))
  })

  val lastGrant = RegInit(0.U(log2Ceil(n).W))
  val chosen = Wire(UInt(log2Ceil(n).W))
  val chosenValid = Wire(Bool())

  val valids = io.in.map(_.valid)

  def findNext(start: UInt, valids: Seq[Bool]): (UInt, Bool) = {
    val best = Wire(UInt(log2Ceil(n).W))
    val bestValid = Wire(Bool())
    best := 0.U
    bestValid := false.B
    for (i <- (n - 1) to 0 by -1) {
      val idx = ((start.asSInt + i.S) % n.S).asUInt
      when(valids(idx)) {
        best := idx
        bestValid := true.B
      }
    }
    (best, bestValid)
  }

  val (fromNext, fromNextValid) = findNext(lastGrant + 1.U, valids)
  val (fromZero, fromZeroValid) = findNext(0.U, valids)

  chosen := Mux(fromNextValid, fromNext, fromZero)
  chosenValid := fromNextValid || fromZeroValid

  when(io.out.fire) {
    lastGrant := chosen
  }

  io.out.valid := chosenValid
  io.out.bits := io.in(chosen).bits

  for (i <- 0 until n) {
    io.in(i).ready := io.out.ready && chosen === i.U && chosenValid
  }

  io.chosen := chosen
}

