package common

import chisel3._
import chisel3.util._

class Fp32 extends Bundle {
  val sign     = Bool()
  val exponent = UInt(8.W)
  val mantissa = UInt(23.W)

  def isZero(): Bool = exponent === 0.U && mantissa === 0.U
  def isInf(): Bool  = exponent === 255.U && mantissa === 0.U
  def isNan(): Bool  = exponent === 255.U && mantissa =/= 0.U
}

object Fp32 {
  def fromWord(word: UInt): Fp32 = {
    val fp = Wire(new Fp32)
    fp.sign     := word(31)
    fp.exponent := word(30, 23)
    fp.mantissa := word(22, 0)
    fp
  }

  def toWord(fp: Fp32): UInt = {
    Cat(fp.sign, fp.exponent, fp.mantissa)
  }

  def fromInteger(int: UInt, signed: Bool): Fp32 = {
    val fp = Wire(new Fp32)
    val absVal = Mux(signed && int(31), -int, int)

    val sign = signed && int(31)

    val leadingZeros = PriorityEncoder(absVal.asBools.reverse)

    val normalizedMantissa = (absVal << leadingZeros)(30, 8)

    val exponent = Mux(absVal === 0.U, 0.U, (31 + 127).U - leadingZeros)

    fp.sign     := sign
    fp.exponent := exponent
    fp.mantissa := normalizedMantissa

    fp
  }
}

