package common

import chisel3._
import chisel3.util._

class FmaCmd extends Bundle {
  val ina = new Fp32
  val inb = new Fp32
  val inc = new Fp32
}

class FmaState1 extends Bundle {
  val mulSign   = Bool()
  val mulExp    = SInt(12.W)
  val mulMant   = UInt(48.W)
  val addSign   = Bool()
  val addExp    = UInt(8.W)
  val addMant   = UInt(24.W)
  val isZero    = Bool()
  val isInf     = Bool()
  val isNan     = Bool()
  val aIsZero   = Bool()
  val bIsZero   = Bool()
  val cIsZero   = Bool()
  val aIsInf    = Bool()
  val bIsInf    = Bool()
  val cIsInf    = Bool()
  val aIsNan    = Bool()
  val bIsNan    = Bool()
  val cIsNan    = Bool()
}

class FmaState2 extends Bundle {
  val sign      = Bool()
  val exp       = SInt(12.W)
  val mantissa  = UInt(50.W)
  val isZero    = Bool()
  val isInf     = Bool()
  val isNan     = Bool()
}

object Fma {
  def FmaStage1(cmd: FmaCmd): FmaState1 = {
    val state1 = Wire(new FmaState1)

    val aIsZero = cmd.ina.isZero()
    val bIsZero = cmd.inb.isZero()
    val cIsZero = cmd.inc.isZero()
    val aIsInf  = cmd.ina.isInf()
    val bIsInf  = cmd.inb.isInf()
    val cIsInf  = cmd.inc.isInf()
    val aIsNan  = cmd.ina.isNan()
    val bIsNan  = cmd.inb.isNan()
    val cIsNan  = cmd.inc.isNan()

    state1.aIsZero := aIsZero
    state1.bIsZero := bIsZero
    state1.cIsZero := cIsZero
    state1.aIsInf  := aIsInf
    state1.bIsInf  := bIsInf
    state1.cIsInf  := cIsInf
    state1.aIsNan  := aIsNan
    state1.bIsNan  := bIsNan
    state1.cIsNan  := cIsNan

    state1.mulSign := cmd.ina.sign ^ cmd.inb.sign
    val aExp = Mux(aIsZero, 1.S, cmd.ina.exponent.asSInt - 127.S)
    val bExp = Mux(bIsZero, 1.S, cmd.inb.exponent.asSInt - 127.S)
    state1.mulExp := aExp + bExp
    val aMant = Cat(!aIsZero, cmd.ina.mantissa)
    val bMant = Cat(!bIsZero, cmd.inb.mantissa)
    state1.mulMant := aMant * bMant

    state1.addSign := cmd.inc.sign
    state1.addExp  := cmd.inc.exponent
    state1.addMant := Cat(!cIsZero, cmd.inc.mantissa)

    state1.isZero := (aIsZero || bIsZero) && cIsZero
    state1.isInf  := (aIsInf || bIsInf) || cIsInf
    state1.isNan  := aIsNan || bIsNan || cIsNan

    state1
  }

  def FmaStage2(state1: FmaState1): FmaState2 = {
    val state2 = Wire(new FmaState2)

    state2.isZero := state1.isZero
    state2.isInf  := state1.isInf
    state2.isNan  := state1.isNan

    val mulMantFull = state1.mulMant

    val addExpSInt = Mux(state1.cIsZero, (-200).S, state1.addExp.asSInt - 127.S)
    val addMantFull = state1.addMant

    val expDiff = state1.mulExp - addExpSInt

    when(expDiff < 0.S) {
      val shift = Mux(expDiff > (-48).S, expDiff.asUInt.negate, 48.U)
      state2.exp  := addExpSInt
      state2.sign := state1.addSign
      val shiftedMul = Mux(shift >= 48.U, 0.U, mulMantFull >> shift)
      when(state1.mulSign ^ state1.addSign) {
        val result = addMantFull - shiftedMul
        when(result(49)) {
          state2.sign := !state1.addSign
          state2.mantissa := -result
        }.otherwise {
          state2.mantissa := result
        }
      }.otherwise {
        state2.mantissa := addMantFull + shiftedMul
      }
    }.otherwise {
      val shift = Mux(expDiff >= 48.S, 48.U, expDiff.asUInt)
      state2.exp  := state1.mulExp
      state2.sign := state1.mulSign
      val shiftedAdd = Mux(shift >= 48.U || state1.cIsZero, 0.U, addMantFull >> shift)
      when(state1.mulSign ^ state1.addSign) {
        val result = mulMantFull - shiftedAdd
        when(result(49)) {
          state2.sign := !state1.mulSign
          state2.mantissa := -result
        }.otherwise {
          state2.mantissa := result
        }
      }.otherwise {
        state2.mantissa := mulMantFull + shiftedAdd
      }
    }

    when(state1.isZero) {
      state2.sign := false.B
    }

    state2
  }

  def FmaStage3(state2: FmaState2): Fp32 = {
    val fp = Wire(new Fp32)

    when(state2.isNan) {
      fp.sign     := false.B
      fp.exponent := 255.U
      fp.mantissa := 1.U
    }.elsewhen(state2.isInf) {
      fp.sign     := state2.sign
      fp.exponent := 255.U
      fp.mantissa := 0.U
    }.elsewhen(state2.isZero || state2.mantissa === 0.U) {
      fp.sign     := false.B
      fp.exponent := 0.U
      fp.mantissa := 0.U
    }.otherwise {
      val mant = state2.mantissa

      val leadingZeros = PriorityEncoder(mant.asBools.reverse)

      val normalized = mant << leadingZeros

      val finalExp = state2.exp - leadingZeros.asSInt + 1.S + 127.S

      when(finalExp > 254.S) {
        fp.sign     := state2.sign
        fp.exponent := 255.U
        fp.mantissa := 0.U
      }.elsewhen(finalExp <= 0.S) {
        fp.sign     := state2.sign
        fp.exponent := 0.U
        fp.mantissa := 0.U
      }.otherwise {
        val roundBit = normalized(22)
        val stickyBit = normalized(21, 0) =/= 0.U
        val lsb = normalized(23)
        val rounded = normalized(46, 23) + Mux(roundBit && (lsb || stickyBit), 1.U, 0.U)
        val carry = rounded > ((1 << 24) - 1).U
        fp.sign     := state2.sign
        fp.exponent := Mux(carry, (finalExp + 1.S).asUInt, finalExp.asUInt)
        fp.mantissa := Mux(carry, rounded(22, 0), rounded(22, 0))
      }
    }
    fp
  }
}

