class CircularBufferMulti[T <: Data](gen: T, n: Int, capacity: Int) extends Module {
  val io = IO(new Bundle {
    val enqValid = Input(UInt(log2Ceil(n + 1).W))
    val enqData  = Input(Vec(n, gen))
    val deqReady = Input(UInt(log2Ceil(n + 1).W))
    val flush    = Input(Bool())

    val nEnqueued = Output(UInt(log2Ceil(capacity + 1).W))
    val dataOut   = Output(Vec(n, gen))
  })

  val buffer = Reg(Vec(capacity, gen))
  val head   = RegInit(0.U(log2Ceil(capacity).W))
  val count  = RegInit(0.U(log2Ceil(capacity + 1).W))

  val actualDeq = Mux(io.deqReady > count, count, io.deqReady)
  val remainingSpace = (capacity.U - count) + actualDeq
  val actualEnq = Mux(io.enqValid > remainingSpace, remainingSpace, io.enqValid)

  for (i <- 0 until n) {
    when(actualEnq > i.U) {
      buffer((head + count + i.U) % capacity.U) := io.enqData(i)
    }
  }

  val newHead = head + actualDeq
  val newCount = count + actualEnq - actualDeq

  when(io.flush) {
    head := 0.U
    count := 0.U
  }.otherwise {
    head := newHead % capacity.U
    count := newCount
  }

  for (i <- 0 until n) {
    io.dataOut(i) := buffer((head + i.U) % capacity.U)
  }

  io.nEnqueued := count
}

