class FeedInInterface[T <: Data](gen: T, n: Int) extends Bundle {
  val nValid = Input(UInt(log2Ceil(n + 1).W))
  val bits   = Input(Vec(n, gen))
  val nReady = Output(UInt(log2Ceil(n + 1).W))
}

class InstructionBuffer[T <: Data](gen: T, n: Int, window: Int) extends Module {
  val io = IO(new Bundle {
    val feedIn    = new FeedInInterface(gen, n)
    val out       = Vec(n, Decoupled(gen))
    val nEnqueued = Output(UInt(log2Ceil(window + 1).W))
    val nSpace    = Output(UInt(log2Ceil(window + 1).W))
    val flush     = Input(Bool())
  })

  val cbm = Module(new CircularBufferMulti(gen, n, window))

  cbm.io.enqValid := io.feedIn.nValid
  cbm.io.enqData  := io.feedIn.bits
  cbm.io.flush    := io.flush

  val deqReadyCount = Wire(UInt(log2Ceil(n + 1).W))
  deqReadyCount := 0.U
  for (i <- 0 until n) {
    io.out(i).valid := (cbm.io.nEnqueued > i.U)
    io.out(i).bits  := cbm.io.dataOut(i)
    when(io.out(i).ready && io.out(i).valid) {
      deqReadyCount := (i + 1).U
    }
  }
  cbm.io.deqReady := deqReadyCount

  io.nEnqueued := cbm.io.nEnqueued
  io.nSpace    := window.U - cbm.io.nEnqueued
  io.feedIn.nReady := Mux(cbm.io.nEnqueued + n.U > window.U,
    window.U - cbm.io.nEnqueued, n.U)
}

