class FIFOState[T <: Data](t: T, val n: Int, val capacity: Int) extends Bundle {
  val buffer = Vec(capacity, t)
  val head   = UInt(log2Ceil(capacity).W)
  val count  = UInt(log2Ceil(capacity + 1).W)

  val idxBits = log2Ceil(capacity)

  def dequeue(deqReady: UInt): FIFOState[T] = {
    val next = Wire(new FIFOState(t, n, capacity))
    val actualDeq = Mux(deqReady > count, count, deqReady)
    next.head := (head + actualDeq) % capacity.U
    next.count := count - actualDeq
    next.buffer := buffer
    next
  }

  def enqueue(enqData: Vec[T], enqValid: UInt): FIFOState[T] = {
    val next = Wire(new FIFOState(t, n, capacity))
    val remainingSpace = capacity.U - count
    val actualEnq = Mux(enqValid > remainingSpace, remainingSpace, enqValid)
    for (i <- 0 until n) {
      when(actualEnq > i.U) {
        next.buffer((head + count + i.U) % capacity.U) := enqData(i)
      }.otherwise {
        next.buffer(i) := buffer(i)
      }
    }
    when(actualEnq <= n.U) {
      for (i <- 0 until n) {
        when(actualEnq > i.U) {
          next.buffer((head + count + i.U) % capacity.U) := enqData(i)
        }
      }
    }
    for (i <- 0 until capacity) {
      var willWrite = false
      for (j <- 0 until n) {
        // Skip compile-time writes; we handle them in the loop above
      }
      when(actualEnq > i.U && i.U < n.U) {
        next.buffer((head + count + i.U) % capacity.U) := enqData(i)
      }
    }
    next.head := head
    next.count := count + actualEnq
    next
  }

  def flush(): FIFOState[T] = {
    val next = Wire(new FIFOState(t, n, capacity))
    next.head := 0.U
    next.count := 0.U
    next.buffer := buffer
    next
  }

  def peek(peekN: Int): Vec[T] = {
    val out = Wire(Vec(peekN, t))
    for (i <- 0 until peekN) {
      out(i) := buffer((head + i.U) % capacity.U)
    }
    out
  }

  def invariant(): Bool = {
    count <= capacity.U
  }
}

object FIFOState {
  def init[T <: Data](capacity: Int, t: T): FIFOState[T] = {
    val state = Wire(new FIFOState(t, 4, capacity))
    state.head := 0.U
    state.count := 0.U
    for (i <- 0 until capacity) {
      state.buffer(i) := 0.U.asTypeOf(t)
    }
    state
  }
}

