class Aligner[T <: Data](t: T, n: Int) extends Module {
  val io = IO(new Bundle {
    val in  = Input(Vec(n, Valid(UInt(t.getWidth.W))))
    val out = Output(Vec(n, Valid(UInt(t.getWidth.W))))
  })

  val prefixSum = Wire(Vec(n, UInt(log2Ceil(n + 1).W)))
  prefixSum(0) := io.in(0).valid.asUInt
  for (i <- 1 until n) {
    prefixSum(i) := prefixSum(i - 1) + io.in(i).valid.asUInt
  }

  for (i <- 0 until n) {
    io.out(i).valid := prefixSum(n - 1) > i.U
    io.out(i).bits := 0.U
  }

  for (i <- 0 until n) {
    for (j <- 0 until n) {
      val destIdx = if (j == 0) 0.U else prefixSum(j - 1)
      when(io.in(j).valid && destIdx === i.U) {
        io.out(i).valid := true.B
        io.out(i).bits := io.in(j).bits
      }
    }
  }
}

