module Aligner #(
    parameter WIDTH = 32,
    parameter N = 4
) (
    input  wire                   in_valid  [N-1:0],
    input  wire [WIDTH-1:0]       in_data   [N-1:0],
    output logic                   out_valid [N-1:0],
    output logic [WIDTH-1:0]       out_data  [N-1:0]
);

    integer i, j;
    integer dest_idx[N-1:0];
    integer total_valid;

    always_comb begin
        for (i = 0; i < N; i = i + 1) begin
            out_valid[i] = 1'b0;
            out_data[i] = {WIDTH{1'b0}};
        end

        total_valid = 0;
        for (i = 0; i < N; i = i + 1) begin
            if (in_valid[i]) begin
                dest_idx[i] = total_valid;
                total_valid = total_valid + 1;
            end
        end

        for (i = 0; i < N; i = i + 1) begin
            if (in_valid[i]) begin
                j = dest_idx[i];
                out_valid[j] = 1'b1;
                out_data[j] = in_data[i];
            end
        end
    end

endmodule

