object RotateVectorLeft {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    for (i <- 0 until n) {
      val srcIdxs = (0 until n).map(s => ((i - s % n + n) % n))
      val srcIdx = MuxLookup(shift, 0.U)(
        (0 until n).map(s => s.U -> srcIdxs(s).U)
