      out(i).valid := MuxLookup(shift, false.B)(
        (0 until n).map(s => s.U -> in(srcIdxs(s)).valid)
      )
      out(i).bits := MuxLookup(shift, 0.U.asTypeOf(chiselTypeOf(in(0).bits)))(
        (0 until n).map(s => s.U -> in(srcIdxs(s)).bits)
      )
    }
    out
  }
}

