object ShiftVectorLeft {
  def apply[T <: Data](in: Vec[Valid[T]], shift: UInt): Vec[Valid[T]] = {
    val n = in.length
    val out = Wire(Vec(n, Valid(chiselTypeOf(in(0).bits))))
    val zero = Wire(Valid(chiselTypeOf(in(0).bits)))
    zero.valid := false.B
    zero.bits := 0.U.asTypeOf(chiselTypeOf(in(0).bits))

    for (i <- 0 until n) {
      val srcIdxs = (0 until n).map { s =>
        val srcIdx = i - s
        if (srcIdx >= 0 && srcIdx < n) srcIdx else -1
      }
      val muxPairs = (0 until n).map { s =>
        val srcIdx = srcIdxs(s)
        if (srcIdx >= 0) s.U -> in(srcIdx) else s.U -> zero
      }
      out(i) := MuxLookup(shift, zero)(muxPairs)
    }
    out
  }
}

