object GenerateInterface {
  def apply(io: Data, prefix: String): String = {
    val lines = scala.collection.mutable.ArrayBuffer[String]()

    def processElement(d: Data, name: String): Unit = {
      d match {
        case b: Bundle =>
          val elements = b.elements.toSeq
          for ((fieldName, fieldData) <- elements) {
            val fullName = s"${name}_${fieldName}"
            processElement(fieldData, fullName)
