          lines += s"${direction} logic${width} ${name}"
      }
    }

    io match {
      case b: Bundle =>
        val elements = b.elements.toSeq
        for ((fieldName, fieldData) <- elements) {
          val fullName = s"${prefix}_${fieldName}"
          processElement(fieldData, fullName)
        }
      case _ =>
        processElement(io, prefix)
    }

