    def directionString(d: Data): String = {
      val dir = DataMirror.directionOf(d)
      if (dir == ActualDirection.Output) "output" else "input "
    }

    def processElement(d: Data, name: String): Unit = {
      d match {
        case b: Bundle =>
          val elements = b.elements.toSeq.reverse
          for ((fieldName, fieldData) <- elements) {
            val fullName = s"${name}_${fieldName}"
            processElement(fieldData, fullName)
          }
        case v: Vec[_] =>
          for (i <- 0 until v.length) {
            processElement(v(i), s"${name}_${i}")
          }
        case _ =>
          val width = d.getWidth match {
            case 1 => ""
            case w => s" [${w - 1}:0]"
          }
          val dir = directionString(d)
          lines += s"  ${dir} logic${width} ${name}"
      }
    }

    io match {
      case b: Bundle =>
        val elements = b.elements.toSeq.reverse
        for ((fieldName, fieldData) <- elements) {
          val fullName = s"${prefix}_${fieldName}"
          processElement(fieldData, fullName)
        }
      case _ =>
        processElement(io, prefix)
    }

    lines.mkString(",\n")
  }
}

